            line-height: 1.5;
        }

        .info strong {
            color: rgba(255,255,255,0.9);
        }
    </style>
</head>
<body>
    <div class="wrapper">
        <canvas id="canvas" width="400" height="400"></canvas>
        <div class="base"></div>
        <div class="info">
            <strong>Interactive Snow Globe</strong><br>
            Drag to rotate | Scroll to zoom
        </div>
    </div>

    <script>
