        const ctx = canvas.getContext('2d');

        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        const globeRadius = 180;

        let rotationX = 0.3;
        let rotationY = 0.5;
        let zoom = 1;
        let animationTime = 0;

        // 3D Vector class
        class Vector3 {
            constructor(x = 0, y = 0, z = 0) {
                this.x = x;
                this.y = y;
                this.z = z;
            }

            rotateX(angle) {
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                return new Vector3(
                    this.x,
                    this.y * cos - this.z * sin,
                    this.y * sin + this.z * cos
                );
            }

            rotateY(angle) {
                const cos = Math.cos(angle);
                const sin = Math.sin(angle);
                return new Vector3(
                    this.x * cos + this.z * sin,
                    this.y,
                    -this.x * sin + this.z * cos
                );
            }

            rotate(angleX, angleY) {
                return this.rotateY(angleY).rotateX(angleX);
            }

            project(fov = 400) {
                const scale = fov / (fov + this.z + 100);
                return {
                    x: centerX + this.x * scale * zoom,
                    y: centerY + this.y * scale * zoom,
                    z: this.z,
                    scale: scale
                };
            }
        }

        // Generate mountain
        function generateMountain() {
            const triangles = [];
            const segments = 20;
            const baseRadius = 70;
            const peakHeight = 90;
            const baseY = -60;

            // Main cone
            for (let i = 0; i < segments; i++) {
                const angle1 = (i / segments) * Math.PI * 2;
                const angle2 = ((i + 1) / segments) * Math.PI * 2;

                const x1 = Math.cos(angle1) * baseRadius;
                const z1 = Math.sin(angle1) * baseRadius;
                const x2 = Math.cos(angle2) * baseRadius;
                const z2 = Math.sin(angle2) * baseRadius;

                // Side faces
                triangles.push({
                    v1: new Vector3(x1, baseY, z1),
                    v2: new Vector3(0, peakHeight, 0),
                    v3: new Vector3(x2, baseY, z2),
                    color: 'rgb(120, 90, 60)',
                    type: 'rock'
                });

                // Snow cap on peak
                if (i < segments / 2) {
                    triangles.push({
                        v1: new Vector3(0, peakHeight, 0),
                        v2: new Vector3(x1, peakHeight - 20, z1),
                        v3: new Vector3(x2, peakHeight - 20, z2),
                        color: 'rgba(255, 255, 255, 0.9)',
                        type: 'snow'
                    });
                }
            }

            // Base platform
            for (let i = 0; i < segments; i++) {
                const angle1 = (i / segments) * Math.PI * 2;
                const angle2 = ((i + 1) / segments) * Math.PI * 2;

                const x1 = Math.cos(angle1) * baseRadius;
                const z1 = Math.sin(angle1) * baseRadius;
                const x2 = Math.cos(angle2) * baseRadius;
                const z2 = Math.sin(angle2) * baseRadius;

                triangles.push({
                    v1: new Vector3(x1, baseY, z1),
                    v2: new Vector3(x2, baseY, z2),
                    v3: new Vector3(0, baseY, 0),
                    color: 'rgb(140, 110, 80)',
                    type: 'base'
                });
            }

            return triangles;
        }

        // Generate snow particles
        function generateSnow(count = 200) {
            const particles = [];
            for (let i = 0; i < count; i++) {
                const angle = Math.random() * Math.PI * 2;
                const radius = Math.random() * 140;
                const height = (Math.random() - 0.5) * 200;

                particles.push({
                    x: Math.cos(angle) * radius,
                    y: height,
                    z: Math.sin(angle) * radius,
                    vy: -0.5 - Math.random() * 0.3,
                    vx: (Math.random() - 0.5) * 0.3,
                    vz: (Math.random() - 0.5) * 0.3,
                    size: Math.random() * 2 + 1,
                    opacity: 0.6 + Math.random() * 0.4
                });
            }
            return particles;
        }

        const mountainTriangles = generateMountain();
        const snowParticles = generateSnow(250);

        // Draw depth-sorted triangles
        function drawTriangle(tri) {
            const p1 = tri.v1.rotate(rotationX, rotationY).project();
            const p2 = tri.v2.rotate(rotationX, rotationY).project();
            const p3 = tri.v3.rotate(rotationX, rotationY).project();

            ctx.fillStyle = tri.color;
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(p3.x, p3.y);
            ctx.closePath();
            ctx.fill();

            if (tri.type === 'rock') {
                ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
                ctx.lineWidth = 0.5;
                ctx.stroke();
            }
        }

