                    const angle = Math.random() * Math.PI * 2;
                    const radius = Math.random() * 140;
                    particle.x = Math.cos(angle) * radius;
                    particle.y = 100;
                    particle.z = Math.sin(angle) * radius;
                }

                // Gentle wind effect
                particle.vx += (Math.sin(animationTime * 0.5 + particle.y) - particle.vx) * 0.01;
                particle.vz += (Math.cos(animationTime * 0.3 + particle.y) - particle.vz) * 0.01;
