            glowGradient.addColorStop(1, 'rgba(50, 100, 180, 0.05)');
            ctx.fillStyle = glowGradient;
            ctx.beginPath();
            ctx.arc(centerX, centerY, globeRadius, 0, Math.PI * 2);
            ctx.fill();

            // Sort and draw mountain triangles
