            isDragging = true;
            prevX = e.clientX || e.touches[0].clientX;
            prevY = e.clientY || e.touches[0].clientY;
        }

        function onMouseMove(e) {
            if (isDragging) {
                const x = e.clientX || e.touches[0].clientX;
                const y = e.clientY || e.touches[0].clientY;
